using Microsoft.AspNetCore.Authorization;
using Microsoft.OpenApi;

namespace InvoiceFlow.Api.Infrastructure.OpenApi;

/// <summary>
/// Configures the OpenAPI document generated by ASP.NET Core, including the
/// Bearer security scheme used by Swagger UI.
/// </summary>
internal static class OpenApiDocumentation
{
    private const string BearerScheme = "Bearer";

    public static IServiceCollection AddInvoiceFlowOpenApi(this IServiceCollection services)
    {
        services.AddOpenApi(options =>
        {
            options.AddDocumentTransformer((document, _, _) =>
            {
                document.Info.Title = "InvoiceFlow API";
                document.Info.Description =
                    "RESTful customer and invoice management API for small businesses.";

                document.Components ??= new OpenApiComponents();
                document.Components.SecuritySchemes ??=
                    new Dictionary<string, IOpenApiSecurityScheme>();

                document.Components.SecuritySchemes[BearerScheme] = new OpenApiSecurityScheme
                {
                    Type = SecuritySchemeType.Http,
                    Scheme = "bearer",
                    BearerFormat = "JWT",
                    Description =
                        "JWT access token returned by POST /api/auth/login. " +
                        "Paste the token only (Swagger UI adds the Bearer prefix).",
                };

                document.Security =
                [
                    new OpenApiSecurityRequirement
                    {
                        [new OpenApiSecuritySchemeReference(BearerScheme, document)] = [],
                    },
                ];

                document.Paths["/health"] = CreateHealthPathItem();

                return Task.CompletedTask;
            });

            options.AddOperationTransformer((operation, context, _) =>
            {
                var allowsAnonymous = context.Description.ActionDescriptor.EndpointMetadata
                    .OfType<IAllowAnonymous>()
                    .Any();

                if (allowsAnonymous)
                {
                    // Registration, login, and other explicitly anonymous endpoints
                    // must not inherit the document-level security requirement.
                    operation.Security = [];
                }

                return Task.CompletedTask;
            });
        });

        return services;
    }

    private static OpenApiPathItem CreateHealthPathItem() =>
        new()
        {
            Operations = new Dictionary<HttpMethod, OpenApiOperation>
            {
                [HttpMethod.Get] = new()
                {
                    Summary = "Reports API readiness, including database connectivity.",
                    Security = [],
                    Responses = new OpenApiResponses
                    {
                        ["200"] = new OpenApiResponse
                        {
                            Description = "The API and its database are healthy.",
                        },
                        ["503"] = new OpenApiResponse
                        {
                            Description = "The API is running but a dependency is unhealthy.",
                        },
                    },
                },
            },
        };
}
